import { Navigate } from "react-router-dom";
import { useAuthState } from "react-firebase-hooks/auth";
import { auth } from "../firebase"; // Ensure correct path
import Index from "views/Index.js";
import Profile from "views/examples/Profile.js";
import Register from "views/examples/Register.js";
import Login from "views/examples/Login.js";
import Tables from "views/examples/Tables.js";
import Icons from "views/examples/Icons.js";
import CarbonDataInput from "views/examples/datainput";
import CarbonRedemption from "views/examples/redeemcredits";

const ProtectedRoute = ({ component }) => {
  const [user, loading] = useAuthState(auth);
  if (loading) return null; // Prevent flickering
  return user ? component : <Navigate to="/auth/login" />;
};

var routes = [
  {
    path: "/login",
    name: "Login",
    component: <Login />,
    layout: "/auth",
  },
  {
    path: "/register",
    name: "Register",
    component: <Register />,
    layout: "/auth",
  },

  // Default route (redirect to login if not logged in)
  {
    path: "*",
    component: <Navigate to="/auth/login" />,
    layout: "/auth",
  },

  // Protected Admin Routes (User must be logged in)
  {
    path: "/index",
    name: "EcoCred",
    icon: "ni ni-tv-2 text-primary",
    component: <ProtectedRoute component={<Index />} />,
    layout: "/admin",
  },
  {
    path: "/tables",
    name: "Carbon Actions Log (Activity Log)",
    icon: "ni ni-bullet-list-67 text-red",
    component: <ProtectedRoute component={<Tables />} />,
    layout: "/admin",
  },
  {
    path: "/user-profile",
    name: "User Profile",
    icon: "ni ni-single-02 text-yellow",
    component: <ProtectedRoute component={<Profile />} />,
    layout: "/admin",
  },
  {
    path: "/datainput",
    name: "Carbon Input",
    icon: "ni ni-single-02 text-yellow",
    component: <ProtectedRoute component={<CarbonDataInput />} />,
    layout: "/admin",
  },
  {
    path: "/redeemcredits",
    name: "Redeem Credits",
    icon: "ni ni-single-02 text-yellow",
    component: <ProtectedRoute component={<CarbonRedemption />} />,
    layout: "/admin",
  },
];

export default routes;
